// Fonction pour obtenir une traduction
export const getCalendarText = (lang, path) => {
  const keys = path.split('.');
  let value = calendarTranslations[lang] || calendarTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path;
  }
  
  return value;
};
